local a=require("fcs.comms.protocol")local b={}b.CMD_KIND="eh2_beacon_update"b.ACK_KIND="eh2_beacon_update_ack"b.CMD2_KIND="eh2_beacon_cmd"b.STATUS_KIND="eh2_beacon_status"b.OPS={enable=true,disable=true,verify=true,query=true,setPos=true,setInterval=true,reboot=true}function b.cmd(c,d,e)return{k=b.CMD2_KIND,op=c,token=d,args=e}end;function b.validToken(f)return type(f)=="string"and f:gsub("%s","")~=""end;function b.command(d)return{k=b.CMD_KIND,token=d}end;function b.ack(g)return{k=b.ACK_KIND,id=g}end;function b.encode(h)return a.encode(h)end;function b.decode(i)local j=a.decode(i)if type(j)~="table"then return nil end;if j.k==b.CMD_KIND or j.k==b.ACK_KIND then return j end;return nil end;function b.accepts(h,k)if type(h)~="table"or h.k~=b.CMD_KIND then return false end;if not b.validToken(k)then return false end;if not b.validToken(h.token)then return false end;return h.token==k end;return b